import {
  BaseEntity,
  Column,
  CreateDateColumn,
  Entity,
  ManyToOne,
  OneToMany,
  PrimaryGeneratedColumn,
  Tree,
  TreeChildren,
  TreeParent,
  UpdateDateColumn,
} from "typeorm";

@ObjectType()
@Entity()
@Tree("closure-table")
export class Post extends BaseEntity {
  @Field()
  @PrimaryGeneratedColumn("uuid")
  id: string;

  @Field({ nullable: true })
  @Column({ nullable: true })
  parentId?: string;

  @TreeParent()
  parent: Post;

  @Field(() => Int)
  @Column({ default: 1 })
  level: number;

  @Field(() => [Post], { nullable: true })
  @TreeChildren()
  children: Post[] | null;

  @Field()
  @Column({ default: "" })
  title: string;

  @Field()
  @Column({ default: "" })
  text: string;

  @Field({ nullable: true })
  @Column({ nullable: true })
  gifId?: string;

  @Field(() => Int)
  @Column({ default: 0 })
  points: number;

  @Field(() => Int)
  @Column({ default: 0 })
  commentsCount: number;

  @Field()
  @Column({ type: "double precision" })
  ranking: number;

  @Field()
  @Column({ default: false })
  edited: boolean;

  @Field(() => Int, { nullable: true })
  voteStatus: number | null; // 1 or -1 or null

  @Field()
  @Column()
  creatorId: string;

  /* Post structure is more complicated so we cannot just set onDelete: "CASCADE"
  when deleting the user and will have to manually delete ourselves :C */
  @Field(() => User)
  @ManyToOne(() => User, (user) => user.posts)
  creator: User;

  @OneToMany(() => Updoot, (updoot) => updoot.post)
  updoots: Updoot[];

  @Field()
  @CreateDateColumn()
  createdAt: Date;

  @Field()
  @UpdateDateColumn()
  updatedAt: Date;
}
